input.command:
f=$(grep -l 'task_started' .suspense/history/*.json | head -1); echo $f; python3 - "$f" <<'EOF'
import json,sys,re
d=json.load(open(sys.argv[1]))
s=json.dumps(d)
def walk(o,path=""):
    if isinstance(o,dict):
        for k,v in o.items(): walk(v,path+"."+k)
    elif isinstance(o,list):
        for i,v in enumerate(o): walk(v,path+f"[{i}]")
    elif isinstance(o,str) and ('task_started' in o or 'task_notification' in o or 'task_progress' in o):
        for line in o.splitlines():
            if 'task_' in line and '"system"' in line: print(path, line[:700])
walk(d)
print(list(d.keys()) if isinstance(d,dict) else type(d))
EOF

